        curve = []
        for x in product(range(2), repeat=n):
            y = f[x[0]*2**(n-1) + sum(x[i]*2**(i-1) for i in range(1, n))]
            curve.append([x + (y,) if len(x) == n else None])
        return [point for point in curve if point is not None]

    def matrix_rank_variance(A):
        m = len(A)
